import React, { useState, useEffect, useCallback } from "react";
import styled from "styled-components";
import { motion } from "framer-motion";
import { collection, getDocs, addDoc, updateDoc, doc, deleteDoc } from "firebase/firestore";
import { db } from "../services/firebaseConfig";
import { useAuth } from "../contexts/AuthContext";
import PageContainer, { PageHeader, PageTitle, PageSubtitle } from "../components/PageContainer";

// ============= STYLES =============

const Container = styled(PageContainer)`
  max-width: 100%;
`;

const FormCard = styled.div`
  background: rgba(30, 41, 59, 0.7);
  border: 1px solid rgba(56, 189, 248, 0.15);
  border-radius: var(--radius-lg);
  padding: var(--space-md);
  margin-bottom: var(--space-lg);
  backdrop-filter: blur(8px);

  @media (min-width: 768px) {
    padding: var(--space-lg);
  }
`;

const SectionTitle = styled.h2`
  font-size: var(--fs-lg);
  color: #38bdf8;
  margin-bottom: var(--space-md);
  display: flex;
  align-items: center;
  gap: var(--space-sm);
`;

const FormGrid = styled.div`
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-md);

  @media (min-width: 768px) {
    grid-template-columns: repeat(2, 1fr);
  }
`;

const FormGroup = styled.div`
  display: flex;
  flex-direction: column;
`;

const Label = styled.label`
  font-size: var(--fs-sm);
  color: #cbd5e1;
  margin-bottom: var(--space-xs);
  font-weight: var(--fw-medium);
`;

const Input = styled.input`
  background: #1e293b;
  border: 1px solid #334155;
  color: #f8fafc;
  padding: var(--space-sm) var(--space-md);
  border-radius: var(--radius-md);
  width: 100%;
  font-size: var(--fs-base);
  min-height: 48px;
  outline: none;
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast);

  &:focus {
    border-color: #38bdf8;
    box-shadow: 0 0 0 3px rgba(56, 189, 248, 0.2);
  }

  &::placeholder {
    color: #64748b;
  }
`;

const ColorInput = styled.input`
  background: #1e293b;
  border: 1px solid #334155;
  color: #f8fafc;
  padding: var(--space-xs);
  border-radius: var(--radius-md);
  width: 100%;
  height: 48px;
  cursor: pointer;
  outline: none;
  transition: border-color var(--transition-fast);

  &:focus {
    border-color: #38bdf8;
  }
`;

const Button = styled.button`
  background: ${props => props.$variant === 'primary'
    ? 'linear-gradient(135deg, #38bdf8, #0ea5e9)'
    : 'rgba(51, 65, 85, 0.5)'};
  color: ${props => props.$variant === 'primary' ? '#0f172a' : '#f8fafc'};
  border: ${props => props.$variant === 'secondary' ? '1px solid #334155' : 'none'};
  font-weight: var(--fw-semibold);
  padding: var(--space-sm) var(--space-lg);
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: all var(--transition-fast);
  min-height: 48px;
  flex: ${props => props.$block ? '1' : 'none'};
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-sm);

  &:hover:not(:disabled) {
    transform: translateY(-2px);
    box-shadow: ${props => props.$variant === 'primary'
    ? '0 4px 12px rgba(56, 189, 248, 0.4)'
    : 'none'};
  }

  &:active:not(:disabled) {
    transform: scale(0.98);
  }

  &:disabled {
    opacity: 0.6;
    cursor: not-allowed;
  }
`;

const ButtonGroup = styled.div`
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
  margin-top: var(--space-md);

  @media (min-width: 480px) {
    flex-direction: row;
  }
`;

const ListTitle = styled.h2`
  font-size: var(--fs-xl);
  color: #f8fafc;
  margin-bottom: var(--space-md);
  font-weight: var(--fw-semibold);
`;

const CategoryList = styled.div`
  display: flex;
  flex-direction: column;
  gap: var(--space-md);
`;

const EmptyState = styled.div`
  background: rgba(30, 41, 59, 0.5);
  border: 1px solid rgba(148, 163, 184, 0.1);
  border-radius: var(--radius-lg);
  padding: var(--space-xl);
  text-align: center;

  @media (min-width: 768px) {
    padding: var(--space-2xl);
  }
`;

const EmptyIcon = styled.div`
  font-size: 3rem;
  margin-bottom: var(--space-md);

  @media (min-width: 768px) {
    font-size: 4rem;
  }
`;

const EmptyText = styled.p`
  color: #94a3b8;
  font-size: var(--fs-lg);
  margin-bottom: var(--space-sm);

  @media (min-width: 768px) {
    font-size: var(--fs-base);
  }
`;

const EmptySubtext = styled.p`
  color: #64748b;
  font-size: var(--fs-sm);
`;

const CategoryItem = styled(motion.div)`
  background: rgba(30, 41, 59, 0.8);
  border: 1px solid rgba(56, 189, 248, 0.2);
  border-radius: var(--radius-lg);
  padding: var(--space-md);
  transition: all var(--transition-normal);

  &:hover {
    border-color: rgba(56, 189, 248, 0.4);
    background: rgba(56, 189, 248, 0.1);
  }

  @media (min-width: 768px) {
    padding: var(--space-lg);
  }
`;

const CategoryContent = styled.div`
  display: flex;
  flex-direction: column;
  gap: var(--space-md);

  @media (min-width: 640px) {
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
  }
`;

const CategoryLeft = styled.div`
  display: flex;
  align-items: center;
  gap: var(--space-md);
  flex: 1;
`;

const ColorDot = styled.div`
  width: 24px;
  height: 24px;
  border-radius: 50%;
  border: 2px solid rgba(255, 255, 255, 0.2);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
  flex-shrink: 0;

  @media (min-width: 768px) {
    width: 32px;
    height: 32px;
  }
`;

const CategoryNameInput = styled.input`
  flex: 1;
  background: rgba(15, 23, 42, 0.8);
  border: 1px solid #334155;
  color: #f8fafc;
  padding: var(--space-sm) var(--space-md);
  border-radius: var(--radius-md);
  font-size: var(--fs-base);
  min-height: 48px;
  outline: none;
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast);

  &:focus {
    border-color: #38bdf8;
    box-shadow: 0 0 0 3px rgba(56, 189, 248, 0.2);
  }

  @media (min-width: 768px) {
    font-size: var(--fs-lg);
  }
`;

const CategoryRight = styled.div`
  display: flex;
  align-items: center;
  gap: var(--space-sm);

  @media (min-width: 640px) {
    gap: var(--space-md);
  }
`;

const ColorPicker = styled(ColorInput)`
  width: 60px;
  height: 48px;

  @media (min-width: 768px) {
    width: 80px;
    height: 56px;
  }
`;

const DeleteButton = styled.button`
  background: rgba(51, 65, 85, 0.5);
  color: #f8fafc;
  border: none;
  padding: var(--space-sm) var(--space-md);
  border-radius: var(--radius-md);
  font-size: var(--fs-sm);
  cursor: pointer;
  transition: all var(--transition-fast);
  min-height: 48px;
  display: inline-flex;
  align-items: center;
  justify-content: center;

  &:hover {
    background: rgba(239, 68, 68, 0.2);
    color: #ef4444;
  }

  @media (min-width: 768px) {
    padding: var(--space-sm) var(--space-lg);
    font-size: var(--fs-base);
  }
`;

// ============= MAIN COMPONENT =============

export default function Categories() {
  const { user } = useAuth();
  const [categories, setCategories] = useState([]);
  const [newCategory, setNewCategory] = useState({ name: "", color: "#38bdf8" });
  const [isAdding, setIsAdding] = useState(false);

  const fetchCategories = useCallback(async () => {
    if (!user) return;
    const querySnapshot = await getDocs(collection(db, "users", user.uid, "categories"));
    setCategories(querySnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })));
  }, [user]);

  useEffect(() => { fetchCategories(); }, [fetchCategories]);

  const handleAddCategory = async () => {
    if (!user) {
      alert("Você precisa estar logado para adicionar categorias.");
      return;
    }
    if (!newCategory.name.trim()) {
      alert("Digite o nome da categoria!");
      return;
    }
    setIsAdding(true);
    try {
      await addDoc(collection(db, "users", user.uid, "categories"), newCategory);
      setNewCategory({ name: "", color: "#38bdf8" });
      fetchCategories();
      alert("Categoria adicionada com sucesso!");
    } catch (error) {
      console.error("Erro ao adicionar categoria:", error);
      alert("Erro ao adicionar categoria. Tente novamente.");
    } finally {
      setIsAdding(false);
    }
  };

  const handleDeleteCategory = async (id) => {
    if (!user) {
      alert("Você precisa estar logado para excluir categorias.");
      return;
    }
    if (!window.confirm("Tem certeza que deseja excluir esta categoria?")) return;
    try {
      await deleteDoc(doc(db, "users", user.uid, "categories", id));
      fetchCategories();
      alert("Categoria excluída com sucesso!");
    } catch (error) {
      console.error("Erro ao excluir categoria:", error);
      alert("Erro ao excluir categoria. Tente novamente.");
    }
  };

  const handleUpdateCategory = async (id, name, color) => {
    if (!user) return;
    try {
      const docRef = doc(db, "users", user.uid, "categories", id);
      await updateDoc(docRef, { name: name.trim(), color });
      fetchCategories();
    } catch (error) {
      console.error("Erro ao atualizar categoria:", error);
      alert("Erro ao atualizar categoria.");
    }
  };

  const renderList = () => {
    if (categories.length === 0) {
      return (
        <EmptyState>
          <EmptyIcon>📭</EmptyIcon>
          <EmptyText>Nenhuma categoria criada ainda.</EmptyText>
          <EmptySubtext>Adicione sua primeira categoria acima!</EmptySubtext>
        </EmptyState>
      );
    }

    return (
      <CategoryList>
        {categories.map((cat, index) => (
          <CategoryItem
            key={cat.id}
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ delay: 0.1 * index }}
            whileHover={{ scale: 1.02 }}
          >
            <CategoryContent>
              <CategoryLeft>
                <ColorDot style={{ backgroundColor: cat.color }} />
                <CategoryNameInput
                  type="text"
                  value={cat.name}
                  onChange={(e) => handleUpdateCategory(cat.id, e.target.value, cat.color)}
                  placeholder="Nome da categoria"
                />
              </CategoryLeft>
              <CategoryRight>
                <ColorPicker
                  type="color"
                  value={cat.color}
                  onChange={(e) => handleUpdateCategory(cat.id, cat.name, e.target.value)}
                  aria-label="Selecionar cor"
                />
                <DeleteButton
                  onClick={() => handleDeleteCategory(cat.id)}
                  aria-label="Excluir categoria"
                >
                  🗑️
                </DeleteButton>
              </CategoryRight>
            </CategoryContent>
          </CategoryItem>
        ))}
      </CategoryList>
    );
  };

  return (
    <Container>
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.5 }}
      >
        <PageHeader style={{ marginBottom: 'var(--space-lg)' }}>
          <div>
            <PageTitle>
              🏷️ Gerenciar Categorias
            </PageTitle>
            <PageSubtitle>
              Organize suas transações criando e personalizando categorias
            </PageSubtitle>
          </div>
        </PageHeader>

        {/* Formulário de Adição */}
        <FormCard>
          <SectionTitle>
            ➕ Nova Categoria
          </SectionTitle>

          <FormGrid>
            <FormGroup>
              <Label>Nome da Categoria</Label>
              <Input
                type="text"
                placeholder="Ex: Alimentação, Transporte..."
                value={newCategory.name}
                onChange={(e) => setNewCategory({ ...newCategory, name: e.target.value })}
                onKeyPress={(e) => e.key === 'Enter' && handleAddCategory()}
              />
            </FormGroup>

            <FormGroup>
              <Label>Cor</Label>
              <ColorInput
                type="color"
                value={newCategory.color}
                onChange={(e) => setNewCategory({ ...newCategory, color: e.target.value })}
              />
            </FormGroup>
          </FormGrid>

          <ButtonGroup>
            <Button
              $variant="primary"
              onClick={handleAddCategory}
              disabled={isAdding}
              $block
            >
              {isAdding ? "Adicionando..." : "➕ Adicionar"}
            </Button>
          </ButtonGroup>
        </FormCard>

        {/* Lista de Categorias */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.3 }}
        >
          <ListTitle>
            📋 Categorias Existentes ({categories.length})
          </ListTitle>

          {renderList()}
        </motion.div>
      </motion.div>
    </Container>
  );
}
